import random
import os
from datetime import datetime

class SocialMediaBot:
    def __init__(self, platform, username_pattern, password_pattern, spam_rate=0.1):
        self.platform = platform
        self.username_pattern = username_pattern
        self.password_pattern = password_pattern
        self.spam_rate = spam_rate

    def generate_username(self):
        return f"@{random.randint(100000, 999999)}"

    def generate_password(self):
        return f"P{random.randint(1000, 9999)}{datetime.now().strftime('%S')}"

    def generate_account(self):
        username = self.generate_username()
        password = self.generate_password()
        return {
            "username": username,
            "password": password
        }

    def create_social_media_accounts(self, num_accounts):
        for _ in range(num_accounts):
            account = self.generate_account()
            print(f"Created social media account with username: {account['username']}, password: {account['password']}")

